import JSZip from 'jszip';
import { readFileSync, writeFileSync } from 'fs';

// Packages the About Us "Tom Love Legacy" article into an installable JCR
// content package. The article's JCR XML was generated by the xwalk import
// flow (columns block + default-content text/image sections) and is stored at
// migration-work/jcr-content/about-us/tom-love-legacy.xml.
//
// paths.json maps /content/loves-eds-ue/language-masters/en/ -> /en/, so the
// page node en/about-us/tom-love-legacy delivers at /en/about-us/tom-love-legacy.
const BASE = '/workspace/current';
const SITE = '/content/loves-eds-ue/language-masters/en';
const PAGE = `${SITE}/about-us/tom-love-legacy`;
const VERSION = '1.0';
const OUT = `${BASE}/migration-work/loves-eds-ue/loves-eds-ue-about-us-${VERSION}.zip`;

const articleXml = readFileSync(
  `${BASE}/migration-work/jcr-content/about-us/tom-love-legacy.xml`,
  'utf-8',
);

const zip = new JSZip();
zip.file(`jcr_root${PAGE}/.content.xml`, articleXml);

// Scope the filter to exactly this page node so installing the package only
// creates/updates the about-us/tom-love-legacy page and leaves the rest of the
// en subtree (homepage, nav, footer, other locales) untouched.
zip.file('META-INF/vault/filter.xml', `<?xml version="1.0" encoding="UTF-8"?>
<workspaceFilter version="1.0">
  <filter root="${PAGE}"/>
</workspaceFilter>
`);

zip.file('META-INF/vault/properties.xml', `<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<!DOCTYPE properties SYSTEM "http://java.sun.com/dtd/properties.dtd">
<properties>
  <comment>Love's About Us - Tom Love Legacy article content package</comment>
  <entry key="name">loves-eds-ue-about-us</entry>
  <entry key="group">loves-eds-ue</entry>
  <entry key="version">${VERSION}</entry>
  <entry key="packageType">content</entry>
  <entry key="path">/etc/packages/loves-eds-ue/loves-eds-ue-about-us-${VERSION}.zip</entry>
  <entry key="description">Migrated Love's About Us "Tom Love Legacy" article for ${PAGE}. Images reference /content/dam/loves-eds-ue/en/about - ensure the dam-assets are uploaded to AEM Assets.</entry>
</properties>
`);

const buf = await zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' });
writeFileSync(OUT, buf);
console.log('package:', OUT.replace(`${BASE}/`, ''), '|', buf.length, 'bytes | page:', PAGE);
